"""Metadata processing for report-ledger."""


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    import json

    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        raise ValueError(f"Malformed JSON: {text}")

    if not isinstance(data, list):
        raise ValueError(f"Expected JSON array, got {type(data).__name__}")

    record_count = 0
    total_cents = 0
    first_day = None
    last_day = None

    for record in data:
        if not isinstance(record, dict):
            raise ValueError(f"Expected object in array, got {type(record).__name__}")

        # Check required fields
        tenant = record.get('tenant')
        amount_cents = record.get('amount_cents')
        day = record.get('day')

        if tenant is None or not isinstance(tenant, str) or not tenant:
            raise ValueError(f"Row missing or invalid tenant field: {record}")

        if amount_cents is None:
            raise ValueError(f"Row missing or invalid amount_cents field: {record}")

        if isinstance(amount_cents, bool):
            raise ValueError(f"Row has boolean amount_cents (invalid): {record}")

        if not isinstance(amount_cents, int):
            raise ValueError(f"Row has non-integer amount_cents: {record}")

        if day is None:
            raise ValueError(f"Row missing 'day' field: {record}")

        if not isinstance(day, str):
            raise ValueError(f"Row has non-string 'day' field: {record}")

        # Validate YYYY-MM-DD format using regex
        if not re.match(r'^[0-9]{4}-[0-9]{2}-[0-9]{2}$', day):
            raise ValueError(f"Invalid date format '{day}', expected YYYY-MM-DD")

        # Parse components
        y = int(day[0:4])
        m = int(day[5:7])
        d = int(day[8:10])

        # Validate month 1-12
        if m < 1 or m > 12:
            raise ValueError(f"Invalid month {m} in date '{day}'")

        # Days in month
        days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        # Leap year: divisible by 4, except if divisible by 100 unless also by 400
        if m == 2:
            days_in_month[2] = 29 if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0) else 28

        if d < 1 or d > days_in_month[m]:
            raise ValueError(f"Invalid day {d} for month {m} in date '{day}'")

        record_count += 1
        total_cents += amount_cents

        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        'row_count': record_count,
        'total_cents': total_cents,
        'first_day': first_day,
        'last_day': last_day
    }

